'use strict';
const StudioReview=(()=>{
 const key='spotmatch-editor-review-v1',statuses=['pending','ready','changes','not-relevant'];
 function fingerprint(value){let h=2166136261;for(const c of JSON.stringify(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
 function records(){return [...studioPilots.flatMap(c=>c.activities.map((a,i)=>({id:'activity:'+c.id+':'+a.id,kind:'activity',title:a.title,group:c.title,courseId:c.id,index:i,content:{courseGoal:c.goal,courseEntry:c.entry,courseNeed:c.need,...a,practicePool:a.practiceSet?StudioContent.sets[a.practiceSet.set].items:null},url:'#activity/'+c.id+'/'+i}))),...studioResearch.articles.map(a=>({id:'article:'+a.id,kind:'article',title:a.title,group:'Article summaries',content:a,url:'#research/article/'+a.id})),...studioResearch.journals.map(j=>({id:'journal:'+j.id,kind:'journal',title:j.title,group:'Journal credentials',content:j,url:'#research/journal/'+j.id}))].map(r=>({...r,fingerprint:fingerprint(r.content)}));}
 function read(){try{const x=JSON.parse(localStorage.getItem(key)||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{};}catch{return {};}}
 function decision(record,data=read()){const d=Object.hasOwn(data,record.id)?data[record.id]:null;return {status:d?.fingerprint===record.fingerprint&&statuses.includes(d.status)?d.status:'pending',notes:typeof d?.notes==='string'?d.notes.slice(0,4000):'',stale:!!d&&d.fingerprint!==record.fingerprint};}
 function save(record,status,notes){if(!statuses.includes(status))throw Error('Unknown review status.');const data=read();data[record.id]={fingerprint:record.fingerprint,status,notes:String(notes).slice(0,4000),reviewedAt:new Date().toISOString()};localStorage.setItem(key,JSON.stringify(data));return data;}
 function pack(){return {schemaVersion:1,exportedAt:new Date().toISOString(),reviews:records().filter(r=>Object.hasOwn(read(),r.id)).map(r=>({id:r.id,...read()[r.id]}))};}
 function merge(input){if(input?.schemaVersion!==1||!Array.isArray(input.reviews)||input.reviews.length>500)throw Error('Choose a version 1 review file.');const known=new Map(records().map(r=>[r.id,r])),data=read();let accepted=0,skipped=0;for(const d of input.reviews){if(!d||!known.has(d.id)||!statuses.includes(d.status)||typeof d.notes!=='string'||d.notes.length>4000||typeof d.fingerprint!=='string'||!/^[a-f0-9]{1,8}$/.test(d.fingerprint)||typeof d.reviewedAt!=='string'||!Number.isFinite(Date.parse(d.reviewedAt))){skipped++;continue;}const old=data[d.id];if(old?.reviewedAt&&Date.parse(old.reviewedAt)>Date.parse(d.reviewedAt)){skipped++;continue;}data[d.id]={fingerprint:d.fingerprint,status:d.status,notes:d.notes,reviewedAt:d.reviewedAt};accepted++;}localStorage.setItem(key,JSON.stringify(data));return{accepted,skipped};}
 function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function render({app,esc,heading,bind}){let limit=8;const all=records(),query=new URLSearchParams(location.hash.split('?')[1]||'');let kind=query.get('kind')||'activity',course=query.get('course')||'',search=query.get('q')||'';if(!['activity','article','journal'].includes(kind))kind='activity';
 app.innerHTML=heading('EXPERT WORKSPACE','Review the teaching, then try the play','48 pilot activity placements, 30 article summaries and 15 journal records. Review one course or topic at a time.')+'<section class="studio-review-tools"><p>Your notes stay on this device, separately from practice. Export them to share your decisions. Local decisions do not change published editorial labels. Please leave out child names or personal details.</p><div class="studio-review-actions"><button id="reviewExport" class="secondary">Export my review</button><button id="reviewContent" class="secondary">Download content pack</button><label>Import review<input id="reviewImport" type="file" accept="application/json"></label></div><p id="reviewFileStatus" role="status"></p><form id="reviewFilters"><label>Review<select id="reviewKind"><option value="activity">Pilot activities</option><option value="article">Article summaries</option><option value="journal">Journal credentials</option></select></label><label>Course<select id="reviewCourse"><option value="">All three pilots</option>'+studioPilots.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.title)+'</option>').join('')+'</select></label><label>Find a record<input id="reviewSearch" type="search" placeholder="A goal, title or research topic"></label></form><p id="reviewCount" role="status"></p></section><section id="reviewRecords" class="studio-review-records"></section><button id="reviewMore" class="secondary">Show more records</button>';
 for(const [id,value] of [['reviewKind',kind],['reviewCourse',course]])app.querySelectorAll('#'+id+' option').forEach(o=>{if(o.value===value)o.setAttribute('selected','');else o.removeAttribute('selected');});
 app.querySelector('#reviewSearch').value=search;
 const text=value=>Array.isArray(value)?value.map(text).join('; '):value&&typeof value==='object'?Object.entries(value).map(([k,v])=>k+': '+text(v)).join('; '):value===null?'Not supplied':String(value);
 function fields(r){return Object.entries(r.content).filter(([k])=>!['id','title','practiceSet'].includes(k)).map(([k,v])=>'<div><dt>'+esc(k.replace(/([a-z])([A-Z])/g,'$1 $2'))+'</dt><dd>'+esc(text(v))+'</dd></div>').join('');}
 function draw(){const p=new URLSearchParams({kind});if(course&&kind==='activity')p.set('course',course);if(search)p.set('q',search);history.replaceState(null,'',location.pathname+'#review?'+p.toString());const data=read(),found=all.filter(r=>r.kind===kind&&(!course||kind!=='activity'||r.courseId===course)&&JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));const counts=found.reduce((n,r)=>(n[decision(r,data).status]++,n),{pending:0,ready:0,changes:0,'not-relevant':0});app.querySelector('#reviewCount').textContent=found.length+' records · '+counts.pending+' pending · '+counts.ready+' ready · '+counts.changes+' need changes · '+counts['not-relevant']+' not relevant';app.querySelector('#reviewCourse').disabled=kind!=='activity';app.querySelector('#reviewRecords').innerHTML=found.slice(0,limit).map(r=>{const d=decision(r,data);return '<details class="studio-review-record" data-review-id="'+esc(r.id)+'"><summary><span>'+esc(r.title)+'</span><small>'+esc(r.group)+' · '+(d.stale?'Needs recheck':esc(d.status))+'</small></summary><p><a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+(r.kind==='activity'?'Open activity':'Open research record')+' ↗</a></p><p class="studio-notice">'+(r.kind==='activity'?'Check suitability, progression, meaningful interaction, vocabulary and access. The engine field makes reused games visible.':'Check the original source, population, methods, claim accuracy and limitations. Abstract notes do not replace full-text appraisal.')+'</p><dl>'+fields(r)+'</dl><label>Your decision<select data-review-status>'+statuses.map(s=>'<option value="'+s+'" '+(d.status===s?'selected':'')+'>'+({'pending':'Not reviewed','ready':'Ready for my intended use','changes':'Changes needed','not-relevant':'Not relevant to my review'}[s])+'</option>').join('')+'</select></label><label>Review notes<textarea data-review-notes maxlength="4000" rows="4" placeholder="What should change? What is suitable, and for whom?"></textarea></label><p data-review-saved role="status">'+(d.stale?'Content changed since your saved review. Please recheck before choosing a decision.':'Changes save on this device.')+'</p></details>';}).join('')||'<p>No records match. Try another search.</p>';app.querySelector('#reviewMore').hidden=found.length<=limit;
 app.querySelectorAll('[data-review-id]').forEach(card=>{const record=all.find(r=>r.id===card.dataset.reviewId),select=card.querySelector('[data-review-status]'),notes=card.querySelector('[data-review-notes]');notes.value=decision(record).notes;const persist=()=>{try{save(record,select.value,notes.value);card.querySelector('[data-review-saved]').textContent='Saved on this device.';card.querySelector('summary small').textContent=record.group+' · '+select.value;const found=all.filter(r=>r.kind===kind&&(!course||kind!=='activity'||r.courseId===course)&&JSON.stringify(r).toLowerCase().includes(search.toLowerCase())),n={pending:0,ready:0,changes:0,'not-relevant':0};for(const r of found)n[decision(r).status]++;app.querySelector('#reviewCount').textContent=found.length+' records · '+n.pending+' pending · '+n.ready+' ready · '+n.changes+' need changes · '+n['not-relevant']+' not relevant';}catch{card.querySelector('[data-review-saved]').textContent='Could not save. Keep this page open and copy your notes.';}};select.onchange=persist;notes.oninput=persist;});}
 app.querySelector('#reviewKind').onchange=e=>{kind=e.target.value;limit=8;draw();};app.querySelector('#reviewCourse').onchange=e=>{course=e.target.value;limit=8;draw();};app.querySelector('#reviewSearch').oninput=e=>{search=e.target.value;limit=8;draw();};app.querySelector('#reviewFilters').onsubmit=e=>e.preventDefault();app.querySelector('#reviewMore').onclick=()=>{limit+=8;draw();};app.querySelector('#reviewExport').onclick=()=>download('spot-match-expert-review.json',pack());app.querySelector('#reviewContent').onclick=()=>download('spot-match-review-content.json',{preparedDate:new Date().toISOString(),notice:studioResearch.editorialNotice,records:all});app.querySelector('#reviewImport').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>2000000)throw Error('Choose a review file below 2 MB.');const result=merge(JSON.parse(await file.text()));app.querySelector('#reviewFileStatus').textContent=result.accepted+' reviews imported; '+result.skipped+' skipped. Changed content remains pending.';draw();}catch(error){app.querySelector('#reviewFileStatus').textContent=error.message;}};draw();bind();
 }
 return {records,fingerprint,decision,save,pack,merge,render};
})();
